def classify_triangle_by_sides(p1, p2, p3):
    def distance(p, q):
        return ((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2) ** 0.5

    a = distance(p1, p2)
    b = distance(p2, p3)
    c = distance(p3, p1)

    sides = sorted([a, b, c])

    if sides[0] == sides[1] == sides[2]:
        return 'equilateral'
    elif sides[0] == sides[1] or sides[1] == sides[2]:
        return 'isosceles'
    else:
        return 'scalene'
```

