def is_convex_polygon(points):
    def cross(o, a, b):
        # Returns the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check all consecutive triplets of points
    prev = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        curr = cross(a, b, c)
        if curr == 0:
            return False  # Collinear points, not convex
        if prev * curr < 0:
            return False  # Change in direction, not convex
        prev = curr

    return True
```

