def is_convex_polygon(points):
    def cross_product(o, a, b):
        # Calculate the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Iterate through all consecutive triplets of points
    prev_sign = 0
    for i in range(n):
        o = points[i]
        a = points[(i + 1) % n]
        b = points[(i + 2) % n]
        cross = cross_product(o, a, b)

        # Check if cross product is zero (collinear points)
        if cross == 0:
            return False  # Not a convex polygon if any three points are collinear

        # Check if all cross products have the same sign
        if prev_sign == 0:
            prev_sign = cross
        elif (cross > 0 and prev_sign < 0) or (cross < 0 and prev_sign > 0):
            return False  # Sign changed, not convex

    return True
```

