def equal_under_rotation(grid1, grid2):
    def rotate_90(matrix):
        # Rotate matrix 90 degrees clockwise
        return [list(row)[::-1] for row in zip(*matrix)]

    def rotate_180(matrix):
        # Rotate matrix 180 degrees clockwise
        return [row[::-1] for row in matrix[::-1]]

    def rotate_270(matrix):
        # Rotate matrix 270 degrees clockwise
        return [list(row) for row in zip(*matrix)][::-1]

    # Check if any rotation of grid1 matches grid2
    rotations = [grid1, rotate_90(grid1), rotate_180(grid1), rotate_270(grid1)]
    return any(grid == grid2 for grid in rotations)
```

