def column_with_max_sum(grid):
    if not grid or not grid[0]:
        return -1  # According to problem statement, grid is non-empty and has at least one column

    max_sum = float('-inf')
    result_col = 0

    for col in range(len(grid[0])):
        current_sum = 0
        for row in range(len(grid)):
            current_sum += grid[row][col]
        if current_sum > max_sum or (current_sum == max_sum and col < result_col):
            max_sum = current_sum
            result_col = col

    return result_col
```

