def count_paths(grid):
    rows, cols = len(grid), len(grid[0])

    # If start or end is blocked, return 0
    if grid[0][0] == 1 or grid[rows-1][cols-1] == 1:
        return 0

    # Initialize a DP table with the same dimensions as grid
    dp = [[0 for _ in range(cols)] for _ in range(rows)]
    dp[0][0] = 1  # Starting point has one way to reach itself

    # Fill the first row
    for j in range(1, cols):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            break  # Obstacle encountered, no further paths in this row

    # Fill the first column
    for i in range(1, rows):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            break  # Obstacle encountered, no further paths in this column

    # Fill the rest of the DP table
    for i in range(1, rows):
        for j in range(1, cols):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Blocked cell, no path through here

    return dp[rows-1][cols-1]
```

