            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0  # Obstacle, no way to reach here

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Obstacle, no way to reach here

    return dp[m-1][n-1]
```

