def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True  # Empty grid or single cell is valid

    rows = len(grid)
    cols = len(grid[0])

    # Determine the expected value for cell (i, j)
    def expected_value(i, j):
        return 0 if (i + j) % 2 == 0 else 1

    # Use the first cell's value to determine the two alternating values
    # We'll use 0 and 1 as placeholders; actual values can be anything as long as they differ
    first_val = grid[0][0]
    second_val = grid[0][1] if cols > 1 else grid[1][0] if rows > 1 else first_val

    if first_val == second_val:
        return False  # Adjacent cells must differ

    # Map the actual values to 0 and 1 based on the first cell
    val_to_bit = {first_val: 0, second_val: 1}

    for i in range(rows):
        for j in range(cols):
            expected_bit = expected_value(i, j)
            actual_bit = val_to_bit.get(grid[i][j], -1)
            if actual_bit == -1 or actual_bit != expected_bit:
                return False
    return True
```

