def increment_semver(version, part):
    major, minor, patch = map(int, version.split('.'))

    if part == 'patch':
        patch += 1
    elif part == 'minor':
        minor += 1
        patch = 0
    elif part == 'major':
        major += 1
        minor = 0
        patch = 0
    else:
        raise ValueError("Invalid part name. Must be 'major', 'minor', or 'patch'.")

    return f"{major}.{minor}.{patch}"
```

