def robot_grid_position(commands):
    # Initial position and direction
    x, y = 0, 0
    facing = 'N'

    # Mapping directions to their respective movement vectors
    direction_vectors = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Mapping direction changes for left and right turns
    turn_map = {
        'N': {'L': 'W', 'R': 'E'},
        'E': {'L': 'N', 'R': 'S'},
        'S': {'L': 'E', 'R': 'W'},
        'W': {'L': 'S', 'R': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            facing = turn_map[facing][cmd]
        elif cmd == 'F':
            dx, dy = direction_vectors[facing]
            x += dx
            y += dy

    return (x, y, facing)
```

