    direction_map = {
        'N': (0, 1),
        'S': (0, -1),
        'E': (1, 0),
        'W': (-1, 0)
    }

    # Counter-clockwise rotation (L) changes direction in the order: N -> W -> S -> E -> N
    # Clockwise rotation (R) changes direction in the order: N -> E -> S -> W -> N
    rotation_map = {
        'L': {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'},
        'R': {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            facing = rotation_map[cmd][facing]
        elif cmd == 'F':
            dx, dy = direction_map[facing]
            x += dx
            y += dy

    return (x, y, facing)
