def multi_account_balances(events):
    balances = {}

    for event in events:
        if event[0] == "deposit":
            _, acct, amt = event
            if acct not in balances:
                balances[acct] = 0
            balances[acct] += amt
        elif event[0] == "withdraw":
            _, acct, amt = event
            if acct in balances and balances[acct] >= amt:
                balances[acct] -= amt
        elif event[0] == "transfer":
            _, from_acct, to_acct, amt = event
            if from_acct in balances and balances[from_acct] >= amt:
                balances[from_acct] -= amt
                if to_acct not in balances:
                    balances[to_acct] = 0
                balances[to_acct] += amt

    return balances
