def shopping_cart_total(events):
    cart = {}

    for event in events:
        if event[0] == "add":
            _, item, qty, price = event
            if item in cart:
                # Update the price if new price is different
                if cart[item]["price"] != price:
                    cart[item]["price"] = price
                cart[item]["quantity"] += qty
            else:
                cart[item] = {"quantity": qty, "price": price}
        elif event[0] == "remove":
            _, item, qty = event
            if item in cart and cart[item]["quantity"] > qty:
                cart[item]["quantity"] -= qty
            elif item in cart and cart[item]["quantity"] <= qty:
                del cart[item]
        elif event[0] == "clear":
            cart.clear()

    return sum(item["quantity"] * item["price"] for item in cart.values())
