def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = []
    current_floor = start_floor
    requests_set = set(requests)

    # Check if start_floor is requested and add to stops
    if start_floor in requests_set:
        stops.append(start_floor)

    # Continue moving in the given direction until the end of the building
    while True:
        current_floor += direction
        if direction == 1 and current_floor > top_floor:
            break
        if direction == -1 and current_floor < 1:
            break
        if current_floor in requests_set:
            stops.append(current_floor)

    return stops
```

```python
def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = []
    current_floor = start_floor
    requested_floors = set(requests)

    # Check if start_floor is requested
    if current_floor in requested_floors:
        stops.append(current_floor)
        requested_floors.remove(current_floor)

    # Move in the given direction
    while True:
        current_floor += direction
        if direction == 1:
            if current_floor > top_floor:
                break
        else:
            if current_floor < 1:
                break

        if current_floor in requested_floors:
            stops.append(current_floor)
            requested_floors.remove(current_floor)

    return stops
```

